'use strict';
let europeProbeScenario='season';
function renderEuropeProbe(f,eventLinks){
 if(!f.probe_scenarios)return '';
 const selected=f.probe_scenarios.find(s=>s.id===europeProbeScenario)||f.probe_scenarios[0];
 return `<section class="europe-probe" data-probe-focus="${esc(f.region_key||'europe_focus')}" aria-label="Выбор страны по цели семьи"><p class="section-kicker">ТРИ СТРАНЫ · РАЗНЫЕ ЦЕЛИ</p><h4>Что вы хотите получить от поездки?</h4><p class="audit-footnote">Моя оценка соответствия вашей семье. Выберите цель: рекомендации меняются; опубликованная программа не подтверждает место.</p><div class="europe-probe-tabs" role="group" aria-label="Цель поездки">${f.probe_scenarios.map(s=>`<button type="button" data-europe-probe="${esc(s.id)}" aria-pressed="${s.id===selected.id}">${esc(s.label)}</button>`).join('')}</div><div aria-live="polite"><p>${esc(selected.intro)}</p><div class="europe-shortlist-grid">${selected.countries.map(c=>`<article data-europe-probe-country="${esc(c.iso)}"><p class="section-kicker">${esc(DATA.countries.find(x=>x.iso===c.iso).country)}</p><h5>${esc(c.verdict)}</h5><p>${esc(c.reason)}</p><p class="audit-footnote">${esc(c.gate)}</p><div class="taiwan-route-links">${eventLinks(c.event_ids)}${c.school_ids.map(id=>`<button data-europe-school="${esc(id)}">${esc(DATA.schools.find(s=>s.id===id).name)} · досье ↗</button>`).join('')}</div></article>`).join('')}</div></div><details class="europe-options"><summary>Маршрут на 10–12 лет: навыки, инженерия и свой продукт</summary><p class="audit-footnote">План развития, составленный для семьи. Будущие даты, правила лиг и победы не гарантированы.</p>${f.development_phases.map(c=>`<article><h5>${esc(c.period)} · ${esc(c.title)}</h5><p>${esc(c.detail)}</p></article>`).join('')}</details></section>`;
}
document.addEventListener('click',event=>{
 const b=event.target.closest('[data-europe-probe]');if(!b)return;
 europeProbeScenario=b.dataset.europeProbe;
 const eventLinks=ids=>ids.map(id=>{const e=EVENTS.find(e=>e.id===id);return e?`<button data-open="${esc(id)}">${esc(e.title)} ↗</button>`:''}).join('');
 const panel=b.closest('.europe-probe'),focus=DATA[panel.dataset.probeFocus||'europe_focus'];
 panel.outerHTML=renderEuropeProbe(focus,eventLinks);
 document.querySelector(`[data-europe-probe="${europeProbeScenario}"]`)?.focus({preventScroll:true});
});
function renderEuropeFamilyPicks(f,eventLinks){
 if(!f.family_picks)return '';
 return `<section class="europe-shortlist europe-family-picks" aria-label="Лучшие варианты для вашей семьи"><p class="section-kicker">ВЫБОР ДЛЯ МАТВЕЯ И ОСКАРА · ПРОВЕРКА 02.10.2026</p><h4>${esc(f.family_picks_heading||'С чего я бы начал в этих трёх странах')}</h4><p class="audit-footnote">${esc(f.family_picks_note)}</p><label>Показать <select id="europe-pick-filter"><option value="all">Все варианты</option>${Object.entries({league:"Соревнования и лиги",camp:"Лагеря и короткая проба",school:"Постоянные школы"}).filter(([kind])=>f.family_picks.some(c=>c.kind===kind)).map(([kind,label])=>`<option value="${kind}">${label}</option>`).join('')}</select></label><div class="europe-shortlist-grid">${f.family_picks.map(c=>`<details class="europe-options" data-europe-pick-kind="${esc(c.kind)}"><summary>${esc(c.country)} · ${esc(c.title)}</summary><p>${esc(c.why)}</p><p class="audit-footnote">${esc(c.gate)}</p><div class="taiwan-route-links">${eventLinks(c.event_ids)}${c.school_ids.map(id=>`<button data-europe-school="${esc(id)}">${esc(DATA.schools.find(s=>s.id===id).name)} · досье ↗</button>`).join('')}</div><div class="europe-source-links">${c.source_urls.map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener">Первичный источник ${i+1} ↗</a>`).join('')}</div></details>`).join('')}</div></section>`;
}
document.addEventListener('change',event=>{
 if(event.target.id==='europe-pick-filter')document.querySelectorAll('[data-europe-pick-kind]').forEach(card=>{card.hidden=event.target.value!=='all'&&card.dataset.europePickKind!==event.target.value;});
});
function renderEuropeBaseComparison(f,eventLinks){
 if(!f.base_comparison)return '';
 return `<section class="europe-base-comparison" aria-label="Сравнение трёх стран для вашей семьи"><p class="section-kicker">МОЙ ВЫБОР · ДВА ВОЗРАСТА И ТРИ СТРАНЫ</p><h4>Где я бы начал для вашей семьи</h4><p class="audit-footnote">${esc(f.comparison_note)}</p><div class="europe-decision-grid">${f.base_comparison.map((c,i)=>`<details class="europe-decision" data-europe-base="${esc(c.iso)}" ${i===0?'open':''}><summary><span>${esc(c.country)}</span><strong>${esc(c.label)}</strong><small>Дети, школа, бюджет и проба ↓</small></summary><div><p>${esc(c.conclusion)}</p><dl>${[['Матвей',c.mat],['Оскар',c.osc],['Школа',c.school],['Пример бюджета',c.budget],['Как попробовать',c.trial],['Условия участия',c.gate]].map(([label,value])=>`<dt>${label}</dt><dd>${esc(value)}</dd>`).join('')}</dl><div class="taiwan-route-links">${eventLinks(c.event_ids)}${c.school_ids.map(id=>`<button data-europe-school="${esc(id)}">${esc(DATA.schools.find(s=>s.id===id).name)} · досье ↗</button>`).join('')}</div><div class="europe-source-links">${c.source_urls.map((url,j)=>`<a href="${esc(url)}" target="_blank" rel="noopener">Первичный источник ${j+1} ↗</a>`).join('')}</div></div></details>`).join('')}</div></section>`;
}
function renderEuropeDecisionBlocks(f,eventLinks){
 if(!f.decisions)return '';
 return `<section class="europe-decisions" aria-label="Семейный выбор маршрута"><p class="section-kicker">ВАША ЦЕЛЬ · СРАВНИТЬ ВАРИАНТЫ</p><h4>Где жить, тренироваться и пробовать</h4><p class="audit-footnote">${esc(f.decision_note)}</p><div class="europe-decision-grid">${f.decisions.map((c,i)=>`<details class="europe-decision" data-europe-decision="${esc(c.id)}" ${i===0?'open':''}><summary><span>${esc(c.country)}</span><strong>${esc(c.title)}</strong><small>Открыть условия и маршрут ↓</small></summary><div><p>${esc(c.conclusion)}</p><dl><dt>Матвей</dt><dd>${esc(c.mat)}</dd><dt>Оскар</dt><dd>${esc(c.osc)}</dd><dt>Что требуется подтвердить</dt><dd>${esc(c.gate)}</dd></dl><div class="taiwan-route-links">${eventLinks(c.event_ids)}</div><div class="europe-source-links">${c.source_urls.map((url,j)=>`<a href="${esc(url)}" target="_blank" rel="noopener">Первичный источник ${j+1} ↗</a>`).join('')}</div></div></details>`).join('')}</div></section><section class="europe-age-routes" aria-label="Возрастный маршрут 2026–2030"><p class="section-kicker">2026 → 2030 · ДВА САМОСТОЯТЕЛЬНЫХ УЧАСТНИКА</p><h4>Когда братья могут быть в одной категории</h4><p class="audit-footnote">${esc(f.age_route_note)}</p><div class="europe-age-grid">${f.age_routes.map(r=>`<details data-europe-year="${r.year}" ${r.year===2028?'open':''}><summary><strong>${r.year}</strong><span>Матвей · ${r.mat_age}</span><span>Оскар · ${r.osc_age}</span><small>Маршрут ↓</small></summary><div><dl><dt>Матвей</dt><dd>${esc(r.mat)}</dd><dt>Оскар</dt><dd>${esc(r.osc)}</dd><dt>Одна команда?</dt><dd>${esc(r.together)}</dd></dl><p>${esc(r.technical)}</p></div></details>`).join('')}</div></section><section class="europe-selection"><h4>Как выбрать школу и наставника</h4><div>${f.selection_checks.map(c=>`<article><h5>${esc(c.title)}</h5><p>${esc(c.detail)}</p></article>`).join('')}</div></section>`;
}
function renderEuropeFocus(box,count,f=DATA.europe_focus,downloadName='STEM_Europe_CHE_ESP_FRA'){
 if(!f){box.innerHTML='';return;}
 const countries=f.countries;
 const totals=countries.map(c=>({c,rows:EVENTS.filter(e=>e.iso.includes(c.iso))}));
 count.textContent=totals.map(({c,rows})=>c.name+' · '+rows.length+' карточек').join(' / ')+' · частичная проверка';
 const eventLinks=ids=>ids.map(id=>{const e=EVENTS.find(e=>e.id===id);return e?`<button data-open="${esc(id)}">${esc(e.title)} ↗</button>`:''}).join('');
 const baseComparison=renderEuropeBaseComparison(f,eventLinks);
 const familyPicks=renderEuropeFamilyPicks(f,eventLinks);
 const probe=renderEuropeProbe(f,eventLinks);
 const seasonStops=f.season_stops?`<section class="europe-shortlist" aria-label="Новые даты сезона"><p class="section-kicker">${esc(f.season_kicker||'2026 / 2027 · ОЧНЫЕ ЭТАПЫ И СЕМЕЙНЫЕ ПОЕЗДКИ')}</p><h4>Даты, с которых можно начать планирование</h4><p class="audit-footnote">Дата события, свободное место, язык и право участия проверяются отдельно. В карточках есть условия каждого ребёнка и ссылки организаторов.</p><div class="europe-shortlist-grid">${f.season_stops.map((s,i)=>`<details class="europe-options" data-europe-stop="${i}"><summary>${esc(s.date)} · ${esc(s.title)}</summary><p class="section-kicker">${esc(s.country)}</p><p>${esc(s.detail)}</p><div class="taiwan-route-links">${eventLinks(s.event_ids)}</div></details>`).join('')}</div></section>`:'';
 const decisionBlocks=renderEuropeDecisionBlocks(f,eventLinks);
 const evidenceBlocks=f.evidence_cards?`<section class="europe-shortlist" aria-label="Результаты команд и условия младших программ"><p class="section-kicker">ПРОВЕРЕНО · КОМАНДА, ШКОЛА И ЯЗЫК</p><h4>Что подтверждают реальные результаты</h4><p class="audit-footnote">Место на местном или национальном этапе, квалификация и мировой титул показаны отдельно. Лаборатория и английская школа требуют отдельной проверки младшего наставника.</p><div class="europe-shortlist-grid">${f.evidence_cards.map((c,i)=>`<details class="europe-options" data-europe-evidence="${i}"><summary>${esc(c.title)}</summary><p>${esc(c.detail)}</p><p class="audit-footnote">${esc(c.limit)}</p><div class="taiwan-route-links">${eventLinks(c.event_ids)}${c.school_ids.map(id=>`<button data-europe-school="${esc(id)}">${esc(DATA.schools.find(s=>s.id===id).name)} · досье ↗</button>`).join('')}</div><div class="europe-source-links">${c.source_urls.map((url,j)=>`<a href="${esc(url)}" target="_blank" rel="noopener">Первичный источник ${j+1} ↗</a>`).join('')}</div></details>`).join('')}</div></section>`:'';
 const shortlist=f.shortlist?`<section class="europe-shortlist"><p class="section-kicker">ПЕРВЫЕ ШАГИ · ДЛЯ ВАШЕЙ СЕМЬИ</p><h4>Что проверять в первую очередь</h4><div class="europe-shortlist-grid">${f.shortlist.map(s=>`<article><h5>${esc(s.title)}</h5><p>${esc(s.detail)}</p><div class="taiwan-route-links">${eventLinks(s.event_ids)}</div></article>`).join('')}</div></section>`:'';
 const deeper=c=>[['Город для пробного периода',c.city_route],['Стоимость и технические часы',c.budget],['Что доказано о результатах',c.results_check]].filter(([,v])=>v).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('');
 box.innerHTML=`<div class="taiwan-intro europe-intro"><p class="section-kicker">${esc(f.region_label||'ЕВРОПА · ВОЗРАСТ, ЯЗЫК И ПУТЬ НА ОТБОР')}</p><h4>${f.heading?esc(f.heading):'Три страны.<br>Свой путь каждому ребёнку.'}</h4><p>${esc(f.family)}</p><p>${esc(f.conclusion)}</p><div class="taiwan-route-links">${totals.map(({c,rows})=>`<button class="button secondary" data-country-catalog="${esc(c.iso)}">${esc(c.name)} · все ${rows.length} →</button>`).join('')}</div></div>${probe}${familyPicks}${baseComparison}${seasonStops}${decisionBlocks}${evidenceBlocks}${shortlist}<div class="taiwan-routes europe-routes${countries.length===2?' two-countries':countries.length===4?' four-countries':''}">${countries.map((c,i)=>`<article data-europe-country="${esc(c.iso)}"><span class="audit-index">${String(i+1).padStart(2,'0')}</span><p class="section-kicker">${esc(c.verdict)}</p><h4>${esc(c.name)}</h4><p>${esc(c.reason)}</p><dl><dt>Матвей · 2017</dt><dd>${esc(c.mat)}</dd><dt>Оскар · 2020</dt><dd>${esc(c.osc)}</dd><dt>Лагеря и каникулы</dt><dd>${esc(c.camp)}</dd><dt>Постоянная школа</dt><dd>${esc(c.school)}</dd>${deeper(c)}</dl><p class="audit-footnote">${esc(c.risk)}</p><div class="taiwan-route-links">${c.profile_ids.map(id=>`<button data-audit-league="${esc(id)}">Правила · ${esc(DATA.league_guide.profiles.find(p=>p.id===id).name)} ↗</button>`).join('')}${c.school_ids.map(id=>`<button data-europe-school="${esc(id)}">${esc(DATA.schools.find(s=>s.id===id).name)} · досье ↗</button>`).join('')}</div><details class="europe-options"><summary>Соревнования, лагеря и выставки · ${c.event_ids.length} ключевых карточек</summary><div class="taiwan-route-links">${eventLinks(c.event_ids)}</div></details></article>`).join('')}</div><div class="europe-plan"><h4>Как проверять маршрут перед переездом</h4>${f.steps.map((s,i)=>`<article><span class="audit-index">${i+1}</span><div><h5>${esc(s.title)}</h5><p>${esc(s.detail)}</p></div></article>`).join('')}</div><p class="audit-footnote">${esc(f.limitations)}</p><details class="audit-boundaries"><summary>Прочитанные первичные источники</summary>${f.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a> · ${esc(s.checked)}</p>`).join('')}</details><div class="audit-downloads"><a class="button secondary" href="downloads/${esc(downloadName)}.md" download>Отчёт по странам ↓</a><a class="button secondary" href="downloads/${esc(downloadName)}.json" download>Данные по странам ↓</a></div>`;
}
document.addEventListener('click',event=>{
 const b=event.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-europe-open')){auditState.tab='europe';auditState.query='';setView('about');history.replaceState(null,'','#europe');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-north-europe-open')){auditState.tab='europe-north';auditState.query='';setView('about');history.replaceState(null,'','#europe-north');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-south-europe-open')){auditState.tab='europe-south';auditState.query='';setView('about');history.replaceState(null,'','#europe-south');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-east-asia-open')){auditState.tab='eastasia';auditState.query='';setView('about');history.replaceState(null,'','#eastasia');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-asia-english-open')){auditState.tab='asia-english';auditState.query='';setView('about');history.replaceState(null,'','#asia-english');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-southeast-asia-open')){auditState.tab='southeastasia';auditState.query='';setView('about');history.replaceState(null,'','#southeastasia');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-middleeast-open')){auditState.tab='middleeast';auditState.query='';setView('about');history.replaceState(null,'','#middleeast');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.hasAttribute('data-africa-open')){auditState.tab='africa';auditState.query='';setView('about');history.replaceState(null,'','#africa');requestAnimationFrame(()=>document.querySelector('.europe-intro')?.scrollIntoView({block:'start'}));}
 if(b.dataset.europeSchool)window.openAtlasSchool(b.dataset.europeSchool);
});
